use std::fs;
use std::path::Path;
use std::process::ExitCode;

use callisto_graph::GraphError;
use callisto_model::format::{
    parse_pre_json, write_pre_json, write_pre_json_preserving, PreJsonError, PreMode, PreState,
};
use callisto_model::{ApplyPermit, CommandRunner, PreReport, SCHEMA_VERSION};

use crate::cli::{GlobalArgs, OutputFormat, PreArgs};
use crate::error::CliError;
use crate::output::{emit_line, emit_report, log_line};
use crate::runner::CliCommandRunner;
use crate::workspace::load_workspace;

/// Extracted from [`handle`] so a fake [`CommandRunner`] can exercise the `git add` without shelling out for real.
fn stage_pre_json(runner: &dyn CommandRunner, root: &Path, rel_path: &Path) -> Result<(), CliError> {
    let rel_str = rel_path.to_string_lossy();
    let output = runner.run("git", &["add", rel_str.as_ref()], root)?;
    if !output.success() {
        return Err(callisto_model::CommandError::Failed {
            program: "git".to_string(),
            exit_code: output.exit_code,
            stderr: output.redacted_stderr(),
        }
        .into());
    }
    Ok(())
}

/// A baseline that fits no version grammar is a malformed owned baseline (E114), as in `version`; other damage is E212.
fn parse_existing_pre_json(text: &str) -> Result<PreState, CliError> {
    parse_pre_json(text).map_err(|error| match error {
        PreJsonError::InvalidInitialVersion { .. } => CliError::Graph(GraphError::PreJson(error)),
        other => CliError::PreJson(other),
    })
}

/// Mirrors `add`'s dry-run preview so both commands report the not-yet-written content the same way.
fn preview(global: &GlobalArgs, mode: &str, tag: &str, rel_path: &Path, content: &str) -> Result<(), CliError> {
    let rel_str = rel_path.to_string_lossy();
    match global.format {
        OutputFormat::Json => {
            let report = PreReport {
                schema_version: SCHEMA_VERSION,
                mode: mode.to_string(),
                tag: tag.to_string(),
                path: Some(rel_str.into_owned()),
                content: Some(content.to_string()),
                diagnostics: vec![],
            };
            emit_report(&mut std::io::stdout(), &report, true)?;
        }
        OutputFormat::Text => {
            emit_line(&format!(
                "[DRY-RUN] Would write {rel_str} (no files written)\n\n{content}"
            ))?;
        }
    }

pub(super) fn ignored_paths<R: CommandRunner>(
    runner: &R,
    root: &Path,
    paths: &[PathBuf],
) -> Result<BTreeSet<PathBuf>, GraphError> {
    if paths.is_empty() {
        return Ok(BTreeSet::new());
    }
    // One quiet run answers the usual "none ignored"; only when something is does each path get asked, so no output
    // needs parsing (git quotes unusual names).
    if !any_ignored(runner, root, paths)? {
        return Ok(BTreeSet::new());
    }
    let mut ignored = BTreeSet::new();
    for path in paths {
        if any_ignored(runner, root, std::slice::from_ref(path))? {
            ignored.insert(path.clone());
        }
    }
    Ok(ignored)
}

/// Whether `git check-ignore` names at least one of `paths` as ignored (it prints what it matched, `-q` taking one path only).
fn any_ignored<R: CommandRunner>(runner: &R, root: &Path, paths: &[PathBuf]) -> Result<bool, GraphError> {
    let rendered: Vec<String> = paths.iter().map(|path| path.to_string_lossy().into_owned()).collect();
    let mut args = vec!["check-ignore", "--"];
    args.extend(rendered.iter().map(String::as_str));
    let output = runner.run("git", &args, root)?;
    match output.exit_code {
        Some(0) => Ok(!output.stdout.trim().is_empty()),
        Some(1) => Ok(false),
        exit_code => Err(GraphError::Command(CommandError::Failed {
            program: "git".to_string(),
            exit_code,
            stderr: output.redacted_stderr(),
        })),
    }
}

fn problem(root: &Path, relative: &Path, target: Target, permit: &ApplyPermit) -> Option<String> {
    if relative.is_absolute()
