    let root = dir.path();
    init_repo(root);
    commit_file(root, "packages/odd*/a.txt", b"1\n", "feat: odd");
    commit_file(root, "packages/odd-other/a.txt", b"1\n", "fix: sibling");
    let git = GitAccess::new(root, &SystemGit);

    assert_eq!(summaries(root, None, &["packages/odd*"]), ["feat: odd"]);
